action.command:
cd /workspace/app && grep -n "failed verification" /opt/node/lib/node_modules/pnpm/dist/pnpm.mjs | head; echo ===; cat > /tmp/scan6.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
for (let n=0;n<lines.length;n++){
  if (lines[n].includes("failed verification")) {
    console.log("==== around", n, "====");
    for(let i=Math.max(0,n-15); i<Math.min(lines.length, n+15); i++) console.log(i, lines[i].trim().slice(0,150));
    break;
  }
}
EOF
node /tmp/scan6.mjs

